package com.kangli.qms.api.measurement;
import com.baomidou.mybatisplus.core.conditions.query.LambdaQueryWrapper; import com.baomidou.mybatisplus.extension.plugins.pagination.Page; import com.kangli.qms.common.*; import com.kangli.qms.domain.measurement.entity.*; import com.kangli.qms.domain.measurement.mapper.*; import io.swagger.annotations.*; import org.apache.poi.ss.usermodel.*; import org.apache.poi.xssf.usermodel.XSSFWorkbook; import org.springframework.web.bind.annotation.*; import org.springframework.web.multipart.MultipartFile; import javax.servlet.http.HttpServletResponse; import java.io.*; import java.net.URLEncoder; import java.nio.charset.StandardCharsets; import java.time.*; import java.util.*;
@RestController @RequestMapping("/api/v1/measurement") @Api(tags="计量管理") public class MeasurementController {
 private final MeasuringInstrumentMapper instruments; private final InstrumentCalibrationRecordMapper calibrations; private final InstrumentUsageRecordMapper usages; private final InstrumentLendingRecordMapper lendings; private final InstrumentMaintenanceRecordMapper maintenance; private final InstrumentScrapRecordMapper scraps; private final CalibrationAgencyMapper agencies;private final InstrumentCalibrationTaskMapper tasks;
 public MeasurementController(MeasuringInstrumentMapper a,InstrumentCalibrationRecordMapper b,InstrumentUsageRecordMapper c,InstrumentLendingRecordMapper d,InstrumentMaintenanceRecordMapper e,InstrumentScrapRecordMapper f,CalibrationAgencyMapper g,InstrumentCalibrationTaskMapper h){instruments=a;calibrations=b;usages=c;lendings=d;maintenance=e;scraps=f;agencies=g;tasks=h;}
 @GetMapping public R<PageResult<MeasuringInstrument>> list(@RequestParam(defaultValue="1")int page,@RequestParam(defaultValue="20")int size,@RequestParam(required=false)String keyword,@RequestParam(required=false)String status){LoginUser u=u(); LambdaQueryWrapper<MeasuringInstrument> q=new LambdaQueryWrapper<MeasuringInstrument>().eq(MeasuringInstrument::getPlantCode,u.getPlantCode().name()).eq(has(status),MeasuringInstrument::getStatus,status).and(has(keyword),w->w.like(MeasuringInstrument::getInstrumentCode,keyword).or().like(MeasuringInstrument::getInstrumentName,keyword)).orderByDesc(MeasuringInstrument::getUpdatedAt); return R.ok(PageResult.of(instruments.selectPage(new Page<>(page,size),q)));}
 @GetMapping("/export") public void export(HttpServletResponse response) throws IOException {String p=u().getPlantCode().name();List<MeasuringInstrument> list=instruments.selectList(new LambdaQueryWrapper<MeasuringInstrument>().eq(MeasuringInstrument::getPlantCode,p).orderByAsc(MeasuringInstrument::getInstrumentCode));try(Workbook wb=new XSSFWorkbook()){Sheet s=wb.createSheet("计量器具台账");String[] headers={"器具编号","器具名称","型号","规格","精度等级","测量范围","出厂编号","生产厂家","购置日期","所属部门","存放地点","责任人","状态","校准周期(月)","校准机构","下次校准日期","备注"};Row h=s.createRow(0);for(int i=0;i<headers.length;i++)h.createCell(i).setCellValue(headers[i]);int n=1;for(MeasuringInstrument x:list){Row r=s.createRow(n++);String[] values={x.getInstrumentCode(),x.getInstrumentName(),x.getModel(),x.getSpecification(),x.getAccuracyGrade(),x.getMeasurementRange(),x.getFactorySerialNo(),x.getManufacturer(),str(x.getPurchaseDate()),x.getDepartmentName(),x.getStorageLocation(),x.getKeeperName(),x.getStatus(),String.valueOf(x.getCalibrationCycleMonths()),x.getCalibrationAgency(),str(x.getNextCalibrationDate()),x.getRemark()};for(int i=0;i<values.length;i++)r.createCell(i).setCellValue(values[i]==null?"":values[i]);}response.setContentType("application/vnd.openxmlformats-officedocument.spreadsheetml.sheet");response.setHeader("Content-Disposition","attachment; filename*=UTF-8''"+URLEncoder.encode("计量器具台账.xlsx",StandardCharsets.UTF_8.name()));wb.write(response.getOutputStream());}}
 @PostMapping("/import") public R<Map<String,Integer>> importExcel(@RequestParam("file") MultipartFile file) throws IOException {if(file.isEmpty())throw bad("请选择Excel文件");LoginUser z=u();int created=0,updated=0;try(Workbook wb=WorkbookFactory.create(file.getInputStream())){Sheet s=wb.getSheetAt(0);DataFormatter f=new DataFormatter();for(int i=1;i<=s.getLastRowNum();i++){Row r=s.getRow(i);if(r==null)continue;String code=f.formatCellValue(r.getCell(0)).trim(),name=f.formatCellValue(r.getCell(1)).trim();if(!has(code)&&!has(name))continue;if(!has(code)||!has(name))throw bad("第"+(i+1)+"行器具编号或名称为空");MeasuringInstrument x=instruments.selectOne(new LambdaQueryWrapper<MeasuringInstrument>().eq(MeasuringInstrument::getPlantCode,z.getPlantCode().name()).eq(MeasuringInstrument::getInstrumentCode,code));boolean exists=x!=null;if(!exists){x=new MeasuringInstrument();x.setInstrumentCode(code);x.setPlantCode(z.getPlantCode().name());x.setPlantName(z.getPlantCode().getChineseName());x.setCreatedBy(z.getRealName());x.setQrCode("QMS-MT-"+z.getPlantCode().name()+"-"+code);}x.setInstrumentName(name);x.setModel(cell(f,r,2));x.setSpecification(cell(f,r,3));x.setAccuracyGrade(cell(f,r,4));x.setMeasurementRange(cell(f,r,5));x.setFactorySerialNo(cell(f,r,6));x.setManufacturer(cell(f,r,7));x.setPurchaseDate(date(cell(f,r,8)));x.setDepartmentName(cell(f,r,9));x.setStorageLocation(cell(f,r,10));x.setKeeperName(cell(f,r,11));x.setStatus(has(cell(f,r,12))?cell(f,r,12):"合格可用");x.setCalibrationCycleMonths(integer(cell(f,r,13),12));x.setCalibrationAgency(cell(f,r,14));x.setNextCalibrationDate(date(cell(f,r,15)));x.setRemark(cell(f,r,16));x.setUpdatedBy(z.getRealName());if(exists){instruments.updateById(x);updated++;}else{instruments.insert(x);created++;}}}Map<String,Integer> result=new LinkedHashMap<>();result.put("created",created);result.put("updated",updated);return R.ok(result,"导入完成");}
 @PostMapping public R<MeasuringInstrument> create(@RequestBody MeasuringInstrument x){LoginUser u=u(); if(!has(x.getInstrumentCode())||!has(x.getInstrumentName()))throw bad("请填写器具编号和名称"); x.setId(null);x.setPlantCode(u.getPlantCode().name());x.setPlantName(u.getPlantCode().getChineseName());x.setStatus("合格可用");x.setQrCode("QMS-MT-"+u.getPlantCode().name()+"-"+x.getInstrumentCode());x.setCreatedBy(u.getRealName());x.setUpdatedBy(u.getRealName());instruments.insert(x);return R.ok(x,"器具已创建");}
 @PutMapping("/{id}") public R<MeasuringInstrument> update(@PathVariable Long id,@RequestBody MeasuringInstrument x){MeasuringInstrument old=require(id);x.setId(id);x.setPlantCode(old.getPlantCode());x.setPlantName(old.getPlantName());x.setStatus(old.getStatus());x.setUpdatedBy(u().getRealName());instruments.updateById(x);return R.ok(instruments.selectById(id));}
 @DeleteMapping("/{id}") public R<Void> delete(@PathVariable Long id){MeasuringInstrument x=require(id);long refs=calibrations.selectCount(new LambdaQueryWrapper<InstrumentCalibrationRecord>().eq(InstrumentCalibrationRecord::getInstrumentId,id))+usages.selectCount(new LambdaQueryWrapper<InstrumentUsageRecord>().eq(InstrumentUsageRecord::getInstrumentId,id))+lendings.selectCount(new LambdaQueryWrapper<InstrumentLendingRecord>().eq(InstrumentLendingRecord::getInstrumentId,id))+maintenance.selectCount(new LambdaQueryWrapper<InstrumentMaintenanceRecord>().eq(InstrumentMaintenanceRecord::getInstrumentId,id))+scraps.selectCount(new LambdaQueryWrapper<InstrumentScrapRecord>().eq(InstrumentScrapRecord::getInstrumentId,id));if(refs>0)throw bad("器具已有生命周期记录，不允许删除");instruments.deleteById(x);return R.ok(null,"器具已删除");}
 @GetMapping("/{id}/calibrations") public R<List<InstrumentCalibrationRecord>> calibrationList(@PathVariable Long id){return R.ok(calibrations.selectList(new LambdaQueryWrapper<InstrumentCalibrationRecord>().eq(InstrumentCalibrationRecord::getInstrumentId,id).orderByDesc(InstrumentCalibrationRecord::getCalibrationDate)));}
 @GetMapping("/{id}/history") public R<Map<String,Object>> history(@PathVariable Long id){require(id);Map<String,Object> r=new LinkedHashMap<>();r.put("calibrations",calibrations.selectList(new LambdaQueryWrapper<InstrumentCalibrationRecord>().eq(InstrumentCalibrationRecord::getInstrumentId,id).orderByDesc(InstrumentCalibrationRecord::getCreatedAt)));r.put("usages",usages.selectList(new LambdaQueryWrapper<InstrumentUsageRecord>().eq(InstrumentUsageRecord::getInstrumentId,id).orderByDesc(InstrumentUsageRecord::getUsedAt)));r.put("lendings",lendings.selectList(new LambdaQueryWrapper<InstrumentLendingRecord>().eq(InstrumentLendingRecord::getInstrumentId,id).orderByDesc(InstrumentLendingRecord::getCreatedAt)));r.put("maintenance",maintenance.selectList(new LambdaQueryWrapper<InstrumentMaintenanceRecord>().eq(InstrumentMaintenanceRecord::getInstrumentId,id).orderByDesc(InstrumentMaintenanceRecord::getCreatedAt)));r.put("scraps",scraps.selectList(new LambdaQueryWrapper<InstrumentScrapRecord>().eq(InstrumentScrapRecord::getInstrumentId,id).orderByDesc(InstrumentScrapRecord::getCreatedAt)));return R.ok(r);}
 @GetMapping("/reminders") public R<Map<String,Object>> reminders(){String p=u().getPlantCode().name();Map<String,Object> r=new LinkedHashMap<>();r.put("calibrationDue",instruments.selectList(new LambdaQueryWrapper<MeasuringInstrument>().eq(MeasuringInstrument::getPlantCode,p).le(MeasuringInstrument::getNextCalibrationDate,LocalDate.now().plusDays(30)).ne(MeasuringInstrument::getStatus,"已报废")));r.put("calibrationTasks",tasks.selectList(new LambdaQueryWrapper<InstrumentCalibrationTask>().eq(InstrumentCalibrationTask::getPlantCode,p).in(InstrumentCalibrationTask::getStatus,"待执行","逾期").orderByAsc(InstrumentCalibrationTask::getPlanDate)));r.put("lendingOverdue",lendings.selectList(new LambdaQueryWrapper<InstrumentLendingRecord>().eq(InstrumentLendingRecord::getPlantCode,p).isNull(InstrumentLendingRecord::getReturnedAt).lt(InstrumentLendingRecord::getExpectedReturnDate,LocalDate.now())));return R.ok(r);}
 @GetMapping("/scraps") public R<List<InstrumentScrapRecord>> scrapList(){return R.ok(scraps.selectList(new LambdaQueryWrapper<InstrumentScrapRecord>().eq(InstrumentScrapRecord::getPlantCode,u().getPlantCode().name()).orderByDesc(InstrumentScrapRecord::getCreatedAt)));}
 @GetMapping("/usage-trace") public R<List<InstrumentUsageRecord>> usageTrace(@RequestParam(required=false)String productBatchNo,@RequestParam(required=false)String operatorName){String p=u().getPlantCode().name();return R.ok(usages.selectList(new LambdaQueryWrapper<InstrumentUsageRecord>().eq(InstrumentUsageRecord::getPlantCode,p).eq(has(productBatchNo),InstrumentUsageRecord::getProductBatchNo,productBatchNo).eq(has(operatorName),InstrumentUsageRecord::getOperatorName,operatorName).orderByDesc(InstrumentUsageRecord::getUsedAt)));}
 @GetMapping("/stats") public R<Map<String,Object>> stats(){String p=u().getPlantCode().name();List<MeasuringInstrument> all=instruments.selectList(new LambdaQueryWrapper<MeasuringInstrument>().eq(MeasuringInstrument::getPlantCode,p));Map<String,Long> byStatus=new LinkedHashMap<>();for(MeasuringInstrument x:all)byStatus.put(x.getStatus(),byStatus.getOrDefault(x.getStatus(),0L)+1);List<InstrumentMaintenanceRecord> repairs=maintenance.selectList(new LambdaQueryWrapper<InstrumentMaintenanceRecord>().eq(InstrumentMaintenanceRecord::getPlantCode,p));java.math.BigDecimal cost=repairs.stream().map(InstrumentMaintenanceRecord::getRepairCost).filter(Objects::nonNull).reduce(java.math.BigDecimal.ZERO,java.math.BigDecimal::add);Map<String,Object> r=new LinkedHashMap<>();r.put("total",all.size());r.put("byStatus",byStatus);r.put("maintenanceCount",repairs.size());r.put("maintenanceCost",cost);r.put("scrapCount",all.stream().filter(x->"已报废".equals(x.getStatus())).count());return R.ok(r);}
 @GetMapping("/agencies") public R<List<CalibrationAgency>> agencies(){return R.ok(agencies.selectList(new LambdaQueryWrapper<CalibrationAgency>().eq(CalibrationAgency::getPlantCode,u().getPlantCode().name()).orderByAsc(CalibrationAgency::getAgencyName)));}
 @PostMapping("/agencies") public R<CalibrationAgency> agency(@RequestBody CalibrationAgency x){LoginUser z=u();if(!has(x.getAgencyName()))throw bad("请填写机构名称");x.setId(null);x.setPlantCode(z.getPlantCode().name());x.setPlantName(z.getPlantCode().getChineseName());x.setCreatedBy(z.getRealName());x.setUpdatedBy(z.getRealName());if(!has(x.getStatus()))x.setStatus("有效");agencies.insert(x);return R.ok(x,"外校机构已保存");}
 @PutMapping("/agencies/{id}") public R<CalibrationAgency> agencyUpdate(@PathVariable Long id,@RequestBody CalibrationAgency x){CalibrationAgency old=agencies.selectById(id);if(old==null||!old.getPlantCode().equals(u().getPlantCode().name()))throw bad("外校机构不存在");x.setId(id);x.setPlantCode(old.getPlantCode());x.setPlantName(old.getPlantName());x.setUpdatedBy(u().getRealName());agencies.updateById(x);return R.ok(agencies.selectById(id));}
 @PostMapping("/{id}/calibrations") public R<InstrumentCalibrationRecord> calibrate(@PathVariable Long id,@RequestBody InstrumentCalibrationRecord r){MeasuringInstrument x=require(id);LoginUser u=u();if(!Arrays.asList("合格","不合格","限用").contains(r.getResult()))throw bad("校准结论不正确");r.setId(null);r.setInstrumentId(id);r.setPlantCode(x.getPlantCode());r.setPlantName(x.getPlantName());r.setCreatedBy(u.getRealName());r.setUpdatedBy(u.getRealName());calibrations.insert(r);x.setLastCalibrationDate(r.getCalibrationDate());x.setNextCalibrationDate(r.getValidUntil());x.setStatus("合格".equals(r.getResult())?"合格可用":"不合格");x.setUpdatedBy(u.getRealName());instruments.updateById(x);List<InstrumentCalibrationTask> open=tasks.selectList(new LambdaQueryWrapper<InstrumentCalibrationTask>().eq(InstrumentCalibrationTask::getInstrumentId,id).in(InstrumentCalibrationTask::getStatus,"待执行","逾期"));for(InstrumentCalibrationTask task:open){task.setStatus("已完成");task.setCompletedAt(LocalDateTime.now());task.setUpdatedBy(u.getRealName());tasks.updateById(task);}return R.ok(r,"校准结果已登记");}
 @PostMapping("/{id}/usage") public R<InstrumentUsageRecord> use(@PathVariable Long id,@RequestBody InstrumentUsageRecord r){MeasuringInstrument x=require(id);if(!"合格可用".equals(x.getStatus())||(x.getNextCalibrationDate()!=null&&x.getNextCalibrationDate().isBefore(LocalDate.now())))throw bad("器具当前状态或校准有效期不满足使用条件");LoginUser u=u();r.setId(null);r.setInstrumentId(id);r.setPlantCode(x.getPlantCode());r.setPlantName(x.getPlantName());r.setCreatedBy(u.getRealName());r.setOperatorName(u.getRealName());if(r.getUsedAt()==null)r.setUsedAt(LocalDateTime.now());usages.insert(r);return R.ok(r,"使用记录已登记");}
 @PostMapping("/{id}/lend") public R<InstrumentLendingRecord> lend(@PathVariable Long id,@RequestBody InstrumentLendingRecord r){MeasuringInstrument x=require(id);if(!"合格可用".equals(x.getStatus()))throw bad("当前器具不可借出");if(r.getExpectedReturnDate()==null)throw bad("请填写预计归还日期");LoginUser u=u();r.setId(null);r.setInstrumentId(id);r.setOriginalStatus(x.getStatus());r.setPlantCode(x.getPlantCode());r.setPlantName(x.getPlantName());r.setCreatedBy(u.getRealName());r.setUpdatedBy(u.getRealName());lendings.insert(r);x.setStatus("借出");x.setUpdatedBy(u.getRealName());instruments.updateById(x);return R.ok(r,"已登记借出");}
 @PostMapping("/lendings/{recordId}/return") public R<InstrumentLendingRecord> returned(@PathVariable Long recordId,@RequestParam(required=false)String appearance){InstrumentLendingRecord r=lendings.selectById(recordId);if(r==null||r.getReturnedAt()!=null)throw bad("借用记录不存在或已归还");MeasuringInstrument x=require(r.getInstrumentId());r.setReturnedAt(LocalDateTime.now());r.setAppearanceResult(appearance);r.setReturnChecker(u().getRealName());lendings.updateById(r);if(has(appearance)&&!"正常".equals(appearance)){InstrumentMaintenanceRecord m=new InstrumentMaintenanceRecord();m.setInstrumentId(x.getId());m.setFaultDescription("归还外观检查异常："+appearance);m.setFinderName(u().getRealName());m.setFoundAt(LocalDateTime.now());m.setStatus("维修中");m.setPlantCode(x.getPlantCode());m.setPlantName(x.getPlantName());m.setCreatedBy(u().getRealName());m.setUpdatedBy(u().getRealName());maintenance.insert(m);x.setStatus("维修中");}else x.setStatus("合格可用".equals(r.getOriginalStatus())&& (x.getNextCalibrationDate()==null||!x.getNextCalibrationDate().isBefore(LocalDate.now()))?"合格可用":"超期");instruments.updateById(x);return R.ok(r,"已归还");}
 @PostMapping("/{id}/return") public R<InstrumentLendingRecord> returnByInstrument(@PathVariable Long id,@RequestParam(required=false)String appearance){require(id);InstrumentLendingRecord r=lendings.selectOne(new LambdaQueryWrapper<InstrumentLendingRecord>().eq(InstrumentLendingRecord::getInstrumentId,id).isNull(InstrumentLendingRecord::getReturnedAt).orderByDesc(InstrumentLendingRecord::getCreatedAt).last("LIMIT 1"));if(r==null)throw bad("未找到待归还的借用记录");return returned(r.getId(),appearance);}
 @PostMapping("/{id}/repair") public R<InstrumentMaintenanceRecord> repair(@PathVariable Long id,@RequestBody InstrumentMaintenanceRecord r){MeasuringInstrument x=require(id);LoginUser u=u();r.setId(null);r.setInstrumentId(id);r.setPlantCode(x.getPlantCode());r.setPlantName(x.getPlantName());r.setCreatedBy(u.getRealName());r.setUpdatedBy(u.getRealName());if(r.getFoundAt()==null)r.setFoundAt(LocalDateTime.now());maintenance.insert(r);x.setStatus("维修中");instruments.updateById(x);return R.ok(r,"报修已登记，器具已锁定");}
 @PostMapping("/maintenance/{recordId}/complete") public R<InstrumentMaintenanceRecord> completeRepair(@PathVariable Long recordId,@RequestBody InstrumentMaintenanceRecord input){InstrumentMaintenanceRecord r=maintenance.selectById(recordId);if(r==null||!r.getPlantCode().equals(u().getPlantCode().name()))throw bad("维修记录不存在");if(!has(input.getRepairContent())||input.getRepairDate()==null)throw bad("请填写维修内容和维修日期");r.setRepairVendor(input.getRepairVendor());r.setRepairContent(input.getRepairContent());r.setRepairCost(input.getRepairCost());r.setRepairDate(input.getRepairDate());r.setStatus("待校准");r.setUpdatedBy(u().getRealName());maintenance.updateById(r);MeasuringInstrument x=require(r.getInstrumentId());x.setStatus("待校准");x.setUpdatedBy(u().getRealName());instruments.updateById(x);return R.ok(r,"维修已完成，请重新校准合格后复用");}
 @PostMapping("/{id}/scrap") public R<InstrumentScrapRecord> scrap(@PathVariable Long id,@RequestBody InstrumentScrapRecord r){MeasuringInstrument x=require(id);LoginUser u=u();r.setId(null);r.setInstrumentId(id);r.setPlantCode(x.getPlantCode());r.setPlantName(x.getPlantName());r.setApplicantName(u.getRealName());r.setCreatedBy(u.getRealName());r.setUpdatedBy(u.getRealName());scraps.insert(r);return R.ok(r,"报废申请已提交");}
 @PostMapping("/scraps/{recordId}/approve") public R<InstrumentScrapRecord> approve(@PathVariable Long recordId,@RequestParam String stage){InstrumentScrapRecord r=scraps.selectById(recordId);if(r==null)throw bad("报废申请不存在");if("METROLOGY".equals(stage)){r.setMetrologyApprover(u().getRealName());r.setStatus("待质量审批");}else if("QUALITY".equals(stage)){if(r.getMetrologyApprover()==null)throw bad("请先完成计量管理员审批");r.setQualityApprover(u().getRealName());r.setStatus("已批准");r.setApprovedAt(LocalDateTime.now());MeasuringInstrument x=require(r.getInstrumentId());x.setStatus("已报废");instruments.updateById(x);}else throw bad("审批阶段不正确");scraps.updateById(r);return R.ok(r,"报废审批已完成");}
 private MeasuringInstrument require(Long id){MeasuringInstrument x=instruments.selectById(id);if(x==null||!x.getPlantCode().equals(u().getPlantCode().name()))throw new BusinessException(ResultCode.NOT_FOUND,"器具不存在");return x;}private LoginUser u(){LoginUser x=LoginUserHolder.get();if(x==null||x.getPlantCode()==null)throw new BusinessException(ResultCode.UNAUTHORIZED,"未获取到登录用户信息");return x;}private boolean has(String s){return s!=null&&!s.trim().isEmpty();}private BusinessException bad(String s){return new BusinessException(ResultCode.BAD_REQUEST,s);}
 private String str(Object x){return x==null?"":String.valueOf(x);}private String cell(DataFormatter f,Row r,int i){return f.formatCellValue(r.getCell(i)).trim();}private LocalDate date(String s){if(!has(s))return null;try{return LocalDate.parse(s);}catch(Exception e){throw bad("日期格式必须为yyyy-MM-dd："+s);}}private Integer integer(String s,int d){if(!has(s))return d;try{return Integer.valueOf(s.replace(".0",""));}catch(Exception e){throw bad("校准周期格式不正确："+s);}}
}
